// Every group of goods and services in posts/singapore-value-buys/post.md, which held them as tables until 11 November 2026.
// Official figures end at September 2026. Shop prices are from 8 and 9 November 2026.
// A move is one thing to do, and a check is one thing to look for on a pack. Their text takes Markdown links. "worth" is a
// figure the post already gives, and it stays empty where the post gives none.
export interface Move { lead: string; text: string; worth: string }
// A good, the pick for it, and why.
export type Pick = readonly [string, string, string];
// An average retail price: name with its pack, price in Sep 2026, change in a year, change a year over the long run,
// Sep 2027 forecast, good deal price, month pattern. Fuel has no good deal price.
export type Official = readonly [string, string, string, string, string, string, string];
// A price index: name, index in Sep 2026, change in a year, change since Sep 2015, Sep 2027 forecast, month pattern.
export type Series = readonly [string, string, string, string, string, string];
// Item, product, link, shop, price, what it covers, unit price, and 1 where the price is a search listing and not an opened page.
export type Shelf = readonly [string, string, string, string, string, string, string, number];
export interface LifeCategory {
  name: string;
  id: string;
  area: string;
  moves: readonly Move[];
  notes: readonly string[];
  checks: readonly Move[];
  picks: readonly Pick[];
  official: readonly Official[];
  series: readonly Series[];
  shelf: readonly Shelf[];
}

